import {buildBVH,sunSteps,sunlightHours} from './solar.js';
import {radiationSteps,irradiation} from './radiation.js';
self.onmessage=({data})=>{try{const {triangles,samples,settings,weather}=data,bvh=buildBVH(triangles),steps=weather?radiationSteps(weather.records,settings):sunSteps(settings),values=[],components=[];for(let i=0;i<samples.length;i++){if(weather){const c=irradiation(samples[i],steps,triangles,bvh,settings.skyPatches);components.push(c);values.push(c.total);}else values.push(sunlightHours(samples[i],steps,triangles,bvh));if(i%25===0)self.postMessage({progress:i/samples.length});}self.postMessage({values,components,daylight:steps.filter(s=>s.altitude>0).reduce((a,s)=>a+s.hours,0)});}catch(e){self.postMessage({error:e.message});}};
